#!/usr/bin/env python3
"""Isolated remote fixture controller. All process paths are inside the owned run."""
import hashlib
import json
import os
from pathlib import Path
import signal
import subprocess
import sys
import time

ROOT = Path.home() / "sibuna-launch-20261001"
sys.path.insert(0, str(ROOT / "source/benchmarks"))


def read(path):
    try:
        return Path(path).read_text().strip()
    except OSError:
        return None


def environment():
    paths = ["/proc/self/cgroup", "/proc/cpuinfo", "/proc/stat", "/proc/pressure/cpu",
             "/sys/fs/cgroup/cpu.max", "/sys/fs/cgroup/cpu.stat",
             "/sys/fs/cgroup/cpuset.cpus.effective", "/sys/fs/cgroup/memory.max",
             "/sys/devices/system/cpu/cpu0/cpufreq/scaling_governor",
             "/sys/devices/system/cpu/cpu0/cpufreq/energy_performance_preference"]
    binaries = {}
    for path in (ROOT / "runtime").glob("*"):
        if path.is_file():
            binaries[path.name] = hashlib.sha256(path.read_bytes()).hexdigest()
    return {"hostname": os.uname().nodename, "kernel": os.uname().release,
            "affinity": sorted(os.sched_getaffinity(0)), "load": os.getloadavg(),
            "files": {path: read(path) for path in paths}, "binaries": binaries}


def supervise(value):
    directory = ROOT / "processes" / value["name"]
    directory.mkdir(parents=True, exist_ok=True)
    (directory / "command.json").write_text(json.dumps(value["args"]))
    with (directory / "daemon.log").open("ab", buffering=0) as log:
        proc = subprocess.Popen(value["args"], stdout=log, stderr=log, env=fixture_env())
        (directory / "pid").write_text(str(proc.pid))
        (directory / "status").write_text(str(proc.wait()))


def fixture_env():
    return {**os.environ, "PATH": str(ROOT / "runtime") + ":" + os.environ["PATH"],
            "LD_LIBRARY_PATH": str(ROOT / "runtime/lib"),
            "XDG_DATA_HOME": str(ROOT / "caddy-data"),
            "XDG_CONFIG_HOME": str(ROOT / "caddy-config")}


def launch(value):
    directory = ROOT / "processes" / value["name"]
    if directory.exists():
        raise RuntimeError("process name already exists")
    subprocess.Popen([sys.executable, __file__, "supervise", json.dumps(value)],
                     stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL,
                     stderr=subprocess.DEVNULL, start_new_session=True)
    deadline = time.monotonic() + 10
    while time.monotonic() < deadline:
        if (directory / "pid").exists():
            return {"pid": int((directory / "pid").read_text())}
        time.sleep(0.05)
    raise TimeoutError("fixture supervisor did not start")


def stop(value):
    directory = ROOT / "processes" / value["name"]
    if (directory / "status").exists():
        return {"status": int((directory / "status").read_text())}
    pid = int((directory / "pid").read_text())
    command = Path(f"/proc/{pid}/cmdline").read_bytes()
    if str(ROOT).encode() not in command:
        raise RuntimeError("refusing to signal a process outside the owned fixture")
    os.kill(pid, signal.SIGTERM)
    deadline = time.monotonic() + 35
    while time.monotonic() < deadline:
        if (directory / "status").exists():
            return {"status": int((directory / "status").read_text())}
        time.sleep(0.1)
    os.kill(pid, signal.SIGKILL)
    raise TimeoutError("owned fixture failed graceful shutdown")


def sample(value):
    import tools
    os.environ.update(fixture_env())
    tools.drain_time_wait()
    load = value["load"]
    tracker = tools.PeakRss(value["pid"])
    before = tools.cpu_seconds(value["pid"])
    tracker.start()
    try:
        result = tools.wrk(value["port"], value["path"], value["headers"], load,
                           ROOT / "control/wrk.lua")
    finally:
        tracker.stopping.set()
        tracker.join()
    wall = result["duration_us"] / 1e6
    return {"requests": result["requests"], "requests_per_second": result["requests"] / wall,
            "latency_us": result["latency_us"], "errors": result["errors"],
            "cpu_seconds": tools.cpu_seconds(value["pid"]) - before,
            "peak_rss_kib": tracker.peak, "wall_seconds": wall}


def warmup(value):
    import tools
    os.environ.update(fixture_env())
    tools.drain_time_wait()
    load = value["load"]
    tools.wrk(value["port"], value["path"], value["headers"],
              {**load, "seconds": load["warmup_seconds"]}, ROOT / "control/wrk.lua")
    return {}


if __name__ == "__main__":
    operation = sys.argv[1]
    value = json.loads(sys.argv[2]) if len(sys.argv) > 2 else {}
    if operation == "supervise":
        supervise(value)
    else:
        result = {"environment": environment, "launch": lambda: launch(value),
                  "stop": lambda: stop(value), "sample": lambda: sample(value),
                  "warmup": lambda: warmup(value)}[operation]()
        print(json.dumps(result), flush=True)

